  2187  xmlXIncludeIncludeNode(xmlXIncludeCtxtPtr ctxt, int nr) {
  2188      xmlNodePtr cur, end, list, tmp;
  2189
  2190      if (ctxt == NULL)
  2191          return(-1);
  2192      if ((nr < 0) || (nr >= ctxt->incNr))
  2193          return(-1);
  2194      cur = ctxt->incTab[nr]->ref;
  2195      if ((cur == NULL) || (cur->type == XML_NAMESPACE_DECL))
  2196          return(-1);
  2197
  2198      list = ctxt->incTab[nr]->inc;
  2199      ctxt->incTab[nr]->inc = NULL;
  2200
  2201      /*
  2202       * Check against the risk of generating a multi-rooted document
  2203       */
  2204      if ((cur->parent != NULL) &&
  2205          (cur->parent->type != XML_ELEMENT_NODE)) {
  2206          int nb_elem = 0;
  2207
  2208          tmp = list;
  2209          while (tmp != NULL) {
  2210              if (tmp->type == XML_ELEMENT_NODE)
  2211                  nb_elem++;
  2212              tmp = tmp->next;
  2213          }
  2214          if (nb_elem > 1) {
  2215              xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  2216                             XML_XINCLUDE_MULTIPLE_ROOT,
  2217                         "XInclude error: would result in multiple root nodes\n",
  2218                             NULL);
  2219              xmlFreeNodeList(list);
  2220              return(-1);
  2221          }
  2222      }
  2223
  2224      if (ctxt->parseFlags & XML_PARSE_NOXINCNODE) {
  2225          /*
  2226           * Add the list of nodes
  2227           */
  2228          while (list != NULL) {
  2229              end = list;
  2230              list = list->next;
  2231
  2232              xmlAddPrevSibling(cur, end);
  2233          }
  2234          xmlUnlinkNode(cur);
  2235          xmlFreeNode(cur);
  2236      } else {
  2237          xmlNodePtr child, next;
  2238
  2239          /*
  2240           * Change the current node as an XInclude start one, and add an
  2241           * XInclude end one
  2242           */
  2243          if (ctxt->incTab[nr]->fallback)
  2244              xmlUnsetProp(cur, BAD_CAST "href");
  2245          cur->type = XML_XINCLUDE_START;
  2246          /* Remove fallback children */
  2247          for (child = cur->children; child != NULL; child = next) {
  2248              next = child->next;
  2249              xmlUnlinkNode(child);
  2250              xmlFreeNode(child);
  2251          }
  2252          end = xmlNewDocNode(cur->doc, cur->ns, cur->name, NULL);
  2253          if (end == NULL) {
  2254              xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  2255                             XML_XINCLUDE_BUILD_FAILED,
  2256                             "failed to build node\n", NULL);
  2257              xmlFreeNodeList(list);
  2258              return(-1);
  2259          }
  2260          end->type = XML_XINCLUDE_END;
  2261          xmlAddNextSibling(cur, end);
  2262
  2263          /*
  2264           * Add the list of nodes
  2265           */
  2266          while (list != NULL) {
  2267              cur = list;
  2268              list = list->next;
  2269
  2270              xmlAddPrevSibling(end, cur);
  2271          }
  2272      }
  2273
  2274
  2275      return(0);
  2276  }
