  2278  /**
  2358   * @tree: the top of the tree to process
  2359   * @skipRoot: don't process the root node of the tree
  2360   *
  2361   * Implement the XInclude substitution on the XML document @doc
  2362   *
  2363   * Returns 0 if no substitution were done, -1 if some processing failed
  2364   *    or the number of substitutions done.
  2365   */
  2366  static int
  2367  xmlXIncludeDoProcess(xmlXIncludeCtxtPtr ctxt, xmlDocPtr doc, xmlNodePtr tree,
  2368                       int skipRoot) {
  2369      xmlNodePtr cur;
  2370      int ret = 0;
  2371      int i, start;
  2372
  2373      if ((doc == NULL) || (tree == NULL) || (tree->type == XML_NAMESPACE_DECL))
  2374          return(-1);
  2375      if ((skipRoot) && (tree->children == NULL))
  2376          return(-1);
  2377      if (ctxt == NULL)
  2378          return(-1);
  2379
  2380      if (doc->URL != NULL) {
  2381          ret = xmlXIncludeURLPush(ctxt, doc->URL);
  2382          if (ret < 0)
  2383              return(-1);
  2384      }
  2385      start = ctxt->incNr;
  2386
  2387      /*
  2388       * TODO: The phases must run separately for recursive inclusions.
  2389       *
  2390       * - Phase 1 should start with top-level XInclude nodes, load documents,
  2391       *   execute XPointer expressions, then process only the result nodes
  2392       *   (not whole document, see bug #324081) and only for phase 1
  2393       *   recursively. We will need a backreference from xmlNodes to
  2394       *   xmlIncludeRefs to detect references that were already visited.
  2395       *   This can also be used for proper cycle detection, see bug #344240.
  2396       *
  2397       * - Phase 2 should visit all top-level XInclude nodes and expand
  2398       *   possible subreferences in the replacement recursively.
  2399       *
  2400       * - Phase 3 should finally replace the top-level XInclude nodes.
  2401       *   It could also be run together with phase 2.
  2402       */
  2403
  2404      /*
  2405       * First phase: lookup the elements in the document
  2406       */
  2407      if (skipRoot)
  2408          cur = tree->children;
  2409      else
  2410          cur = tree;
  2411      do {
  2412          /* TODO: need to work on entities -> stack */
  2413          if (xmlXIncludeTestNode(ctxt, cur) == 1) {
  2414  #ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
  2415              /*
  2416               * Avoid superlinear expansion by limiting the total number
  2417               * of replacements.
  2418               */
  2419              if (ctxt->incTotal >= 20)
  2420                  return(-1);
  2421  #endif
  2422              ctxt->incTotal++;
  2423              xmlXIncludePreProcessNode(ctxt, cur);
  2424          } else if ((cur->children != NULL) &&
  2425                     (cur->children->type != XML_ENTITY_DECL) &&
  2426                     (cur->children->type != XML_XINCLUDE_START) &&
  2427                     (cur->children->type != XML_XINCLUDE_END)) {
  2428              cur = cur->children;
  2429              continue;
  2430          }
  2431          do {
  2432              if (cur == tree)
  2433                  break;
  2434              if (cur->next != NULL) {
  2435                  cur = cur->next;
  2436                  break;
  2437              }
  2438              cur = cur->parent;
  2439          } while (cur != NULL);
  2440      } while ((cur != NULL) && (cur != tree));
  2441
  2442      /*
  2443       * Second Phase : collect the infosets fragments
  2444       */
  2445      for (i = start;i < ctxt->incNr; i++) {
  2446          xmlXIncludeLoadNode(ctxt, i);
  2447          ret++;
  2448      }
  2449
  2450      /*
  2451       * Third phase: extend the original document infoset.
  2452       *
  2453       * Originally we bypassed the inclusion if there were any errors
  2454       * encountered on any of the XIncludes.  A bug was raised (bug
  2455       * 132588) requesting that we output the XIncludes without error,
  2456       * so the check for inc!=NULL || xptr!=NULL was put in.  This may
  2457       * give some other problems in the future, but for now it seems to
  2458       * work ok.
  2459       *
  2460       */
  2461      for (i = ctxt->incBase;i < ctxt->incNr; i++) {
  2462          if (ctxt->incTab[i]->skip == 0)
  2463              xmlXIncludeIncludeNode(ctxt, i);
  2464      }
  2465
  2466      if (doc->URL != NULL)
  2467          xmlXIncludeURLPop(ctxt);
  2468      return(ret);
  2469  }
