  1950  /**
  1951   * xmlXIncludeLoadFallback:
  1952   * @ctxt:  the XInclude context
  1953   * @fallback:  the fallback node
  1954   * @nr:  the xinclude node number
  1955   *
  1956   * Load the content of the fallback node, and store the result
  1957   * in the XInclude context
  1958   *
  1959   * Returns 0 in case of success, -1 in case of failure
  1960   */
  1961  static int
  1962  xmlXIncludeLoadFallback(xmlXIncludeCtxtPtr ctxt, xmlNodePtr fallback, int nr) {
  1963      xmlXIncludeCtxtPtr newctxt;
  1964      int ret = 0;
  1965      int oldNbErrors = ctxt->nbErrors;
  1966
  1967      if ((fallback == NULL) || (fallback->type == XML_NAMESPACE_DECL) ||
  1968          (ctxt == NULL))
  1969          return(-1);
  1970      if (fallback->children != NULL) {
  1971          /*
  1972           * It's possible that the fallback also has 'includes'
  1973           * (Bug 129969), so we re-process the fallback just in case
  1974           */
  1975          newctxt = xmlXIncludeNewContext(ctxt->doc);
  1976          if (newctxt == NULL)
  1977              return (-1);
  1978          newctxt->_private = ctxt->_private;
  1979          newctxt->base = xmlStrdup(ctxt->base);  /* Inherit the base from the existing context */
  1980          xmlXIncludeSetFlags(newctxt, ctxt->parseFlags);
  1981          newctxt->incTotal = ctxt->incTotal;
  1982          if (xmlXIncludeDoProcess(newctxt, ctxt->doc, fallback, 1) < 0)
  1983              ret = -1;
  1984          ctxt->incTotal = newctxt->incTotal;
  1985          if (ctxt->nbErrors > oldNbErrors)
  1986              ret = -1;
  1987          xmlXIncludeFreeContext(newctxt);
  1988
  1989          ctxt->incTab[nr]->inc = xmlDocCopyNodeList(ctxt->doc,
  1990                                                     fallback->children);
  1991      } else {
  1992          ctxt->incTab[nr]->inc = NULL;
  1993      }
  1994      ctxt->incTab[nr]->fallback = 1;
  1995      return(ret);
  1996  }
